mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:091','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:091','preserved':True,'artifacts':['shared_sessions', 'saved_progress', 'hint_history', 'collaboration_history']})+'\n')
